        UINT64 vcboff = 0, vargoff = 0, pcboff = 0, pargoff = 0, vbtoff = 0;
        if (e->sk) { e->sk->tab_on = e->sk->draw_gpu == 2; e->sk->ntok = 0; e->sk->tok[0] = 0; e->sk->nin = 0; }   /* madeira-bcd skin-check */
