    c = mad_list_push((struct mad_list *)This, MC_DRAW_INDEXED);
    if (!c) return;
    c->u.drawi.icount = icount; c->u.drawi.inst = inst; c->u.drawi.start = start;
    c->u.drawi.base = base; c->u.drawi.istart = istart;
